'use client'

import * as React from 'react'
import * as AccordionPrimitive from '@radix-ui/react-accordion'
import { ChevronDownIcon } from 'lucide-react'

import { cn } from '@/lib/utils'

function Accordion({
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Root>) {
  return <AccordionPrimitive.Root data-slot="accordion" {...props} />
}

function AccordionItem({
  className,
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Item>) {
  return (
    <AccordionPrimitive.Item
      data-slot="accordion-item"
      className={cn('border-b last:border-b-0', className)}
      {...props}
    />
  )
}

function AccordionTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Trigger>) {
  return (
    <AccordionPrimitive.Header className="flex">
      <AccordionPrimitive.Trigger
        data-slot="accordion-trigger"
        className={cn(
          'focus-visible:border-ring focus-visible:ring-ring/50 flex flex-1 items-start justify-between gap-4 rounded-md py-4 text-left text-sm font-medium transition-all outline-none hover:underline focus-visible:ring-[3px] disabled:pointer-events-none disabled:opacity-50 [&[data-state=open]>svg]:rotate-180',
          className,
        )}
        {...props}
      >
        {children}
        <ChevronDownIcon className="text-muted-foreground pointer-events-none size-4 shrink-0 translate-y-0.5 transition-transform duration-200" />
      </AccordionPrimitive.Trigger>
    </AccordionPrimitive.Header>
  )
}

function AccordionContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Content>) {
  return (
    <AccordionPrimitive.Content
      data-slot="accordion-content"
      className="data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down overflow-hidden text-sm"
      {...props}
    >
      <div className={cn('pt-0 pb-4', className)}>{children}</div>
    </AccordionPrimitive.Content>
  )
}

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent }

"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { X, Info, CheckCircle2, AlertTriangle, AlertCircle } from "lucide-react"

import { cn } from "@/lib/utils"
import { Link, type LinkProps } from "@/components/ui/link"

const alertVariants = cva(
  "relative w-full rounded-[var(--radius-s)] border p-3 flex items-start gap-3",
  {
    variants: {
      variant: {
        info: "bg-[var(--color-alert-info-bg)] border-[var(--color-alert-info-border)] text-[var(--color-text-primary)] [&>svg]:text-[var(--color-alert-info-icon)]",
        success: "bg-[var(--color-alert-success-bg)] border-[var(--color-alert-success-border)] text-[var(--color-text-primary)] [&>svg]:text-[var(--color-alert-success-icon)]",
        warning: "bg-[var(--color-alert-warning-bg)] border-[var(--color-alert-warning-border)] text-[var(--color-text-primary)] [&>svg]:text-[var(--color-alert-warning-icon)]",
        critical: "bg-[var(--color-alert-critical-bg)] border-[var(--color-alert-critical-border)] text-[var(--color-text-primary)] [&>svg]:text-[var(--color-alert-critical-icon)]",
        // Keep default and destructive for backward compatibility
        default: "bg-card text-card-foreground",
        destructive: "bg-[var(--color-alert-critical-bg)] border-[var(--color-alert-critical-border)] text-[var(--color-text-primary)] [&>svg]:text-[var(--color-alert-critical-icon)]",
      },
    },
    defaultVariants: {
      variant: "info",
    },
  }
)

const variantIcons = {
  info: Info,
  success: CheckCircle2,
  warning: AlertTriangle,
  critical: AlertCircle,
  default: Info,
  destructive: AlertCircle,
} as const

export interface AlertProps
  extends React.ComponentProps<"div">,
    VariantProps<typeof alertVariants> {
  /**
   * If true, shows a close button
   */
  dismissible?: boolean
  /**
   * Callback when close button is clicked
   */
  onDismiss?: () => void
  /**
   * Custom icon to display. If not provided, uses variant-specific icon
   */
  icon?: React.ReactNode
  /**
   * If false, hides the icon
   */
  showIcon?: boolean
}

function Alert({
  className,
  variant = "info",
  dismissible = false,
  onDismiss,
  icon,
  showIcon = true,
  children,
  ...props
}: AlertProps) {
  const [isVisible, setIsVisible] = React.useState(true)

  const handleDismiss = () => {
    onDismiss?.()
    setIsVisible(false)
  }

  if (!isVisible && dismissible) {
    return null
  }

  const IconComponent = variant ? variantIcons[variant] : Info
  const role = variant === "warning" || variant === "critical" || variant === "destructive" ? "alert" : "status"

  return (
    <div
      data-slot="alert"
      role={role}
      className={cn(alertVariants({ variant }), className)}
      {...props}
    >
      {showIcon && (
        <span className="flex-shrink-0 mt-0.5">
          {icon ?? <IconComponent className="size-5" aria-hidden="true" />}
        </span>
      )}
      <div className="flex-1 flex flex-col gap-1">
        {children}
      </div>
      {dismissible && (
        <button
          type="button"
          onClick={handleDismiss}
          className="flex-shrink-0 p-1 -m-1 rounded hover:bg-foreground/10 transition-colors"
          aria-label="Dismiss"
        >
          <X className="size-4" />
        </button>
      )}
    </div>
  )
}

function AlertTitle({ className, ...props }: React.ComponentProps<"h3">) {
  return (
    <h3
      data-slot="alert-title"
      className={cn(
        "font-semibold text-sm leading-5 tracking-tight",
        className
      )}
      {...props}
    />
  )
}

function AlertDescription({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-description"
      className={cn(
        "text-sm leading-5 [&_p]:leading-relaxed",
        className
      )}
      {...props}
    />
  )
}

function AlertActions({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-actions"
      className={cn("mt-2 flex items-center gap-2", className)}
      {...props}
    />
  )
}

function AlertLink({ className, size = "sm", ...props }: LinkProps) {
  return (
    <Link
      data-slot="alert-link"
      size={size}
      className={cn("", className)}
      {...props}
    />
  )
}

export { Alert, AlertTitle, AlertDescription, AlertActions, AlertLink }

'use client'

import * as React from 'react'
import * as AlertDialogPrimitive from '@radix-ui/react-alert-dialog'
import { cva, type VariantProps } from 'class-variance-authority'

import { cn } from '@/lib/utils'
import { buttonVariants } from '@/components/ui/button'

// Size type matching Dialog/Modal component
export type AlertDialogSize = 'xs' | 'sm' | 'md' | 'lg'

const alertDialogContentVariants = cva(
  [
    // Base styling matching Dialog (old Modal)
    'bg-[var(--color-surface-foreground)]',
    'rounded-[var(--radius-s)]',
    // No border
    'fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2',
    'z-[201]',
    'outline-none',
    'flex flex-col',
    'gap-6 p-6', // spacing-sp-24
    // Animations
    'data-[state=open]:animate-in data-[state=closed]:animate-out',
    'data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0',
    'data-[state=closed]:zoom-out-[0.96] data-[state=open]:zoom-in-[0.96]',
    'data-[state=closed]:slide-out-to-top-[2%] data-[state=open]:slide-in-from-top-[2%]',
    'duration-150',
  ],
  {
    variants: {
      size: {
        xs: 'w-[500px] min-w-[392px] max-w-[500px] min-h-[260px] max-h-[500px]',
        sm: 'w-[594px] min-w-[594px] max-w-[800px] min-h-[260px] max-h-[800px]',
        md: 'w-[882px] min-w-[882px] max-w-[1050px] min-h-[260px] max-h-[800px]',
        lg: 'w-[1172px] min-w-[1172px] min-h-[400px] max-h-[800px]',
      },
    },
    defaultVariants: {
      size: 'xs',
    },
  }
)

function AlertDialog({
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Root>) {
  return <AlertDialogPrimitive.Root data-slot="alert-dialog" {...props} />
}

function AlertDialogTrigger({
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Trigger>) {
  return (
    <AlertDialogPrimitive.Trigger data-slot="alert-dialog-trigger" {...props} />
  )
}

function AlertDialogPortal({
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Portal>) {
  return (
    <AlertDialogPrimitive.Portal data-slot="alert-dialog-portal" {...props} />
  )
}

function AlertDialogOverlay({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Overlay>) {
  return (
    <AlertDialogPrimitive.Overlay
      data-slot="alert-dialog-overlay"
      className={cn(
        // 25% black backdrop matching Dialog
        'fixed inset-0 z-[200] bg-black/25',
        'data-[state=open]:animate-in data-[state=closed]:animate-out',
        'data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0',
        'duration-150',
        className,
      )}
      {...props}
    />
  )
}

export interface AlertDialogContentProps
  extends React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Content>,
    VariantProps<typeof alertDialogContentVariants> {
  /** Size variant of the alert dialog */
  size?: AlertDialogSize
}

const AlertDialogContent = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Content>,
  AlertDialogContentProps
>(({ className, size = 'xs', ...props }, ref) => {
  const localRef = React.useRef<React.ElementRef<typeof AlertDialogPrimitive.Content> | null>(null)
  const composedRef = React.useCallback(
    (node: React.ElementRef<typeof AlertDialogPrimitive.Content> | null) => {
      localRef.current = node
      if (typeof ref === 'function') {
        ref(node)
      } else if (ref) {
        ;(ref as React.MutableRefObject<React.ElementRef<typeof AlertDialogPrimitive.Content> | null>).current = node
      }
    },
    [ref]
  )
  return (
    <AlertDialogPortal>
      <AlertDialogOverlay />
      <AlertDialogPrimitive.Content
        ref={composedRef}
        data-slot="alert-dialog-content"
        data-size={size}
        className={cn(alertDialogContentVariants({ size }), className)}
        {...props}
      />
    </AlertDialogPortal>
  )
})

AlertDialogContent.displayName = 'AlertDialogContent'

function AlertDialogHeader({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="alert-dialog-header"
      className={cn('flex flex-col gap-2 text-left shrink-0', className)}
      {...props}
    />
  )
}

function AlertDialogBody({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="alert-dialog-body"
      className={cn('flex-1 overflow-y-auto', className)}
      {...props}
    />
  )
}

function AlertDialogFooter({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="alert-dialog-footer"
      className={cn('flex justify-end items-center gap-3 shrink-0 mt-auto', className)}
      {...props}
    />
  )
}

function AlertDialogTitle({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Title>) {
  return (
    <AlertDialogPrimitive.Title
      data-slot="alert-dialog-title"
      className={cn(
        // h4: 20px size, 24px line-height, bold (matching Dialog)
        'text-xl leading-6 font-bold',
        'text-[var(--color-text-primary)]',
        'm-0',
        className
      )}
      {...props}
    />
  )
}

function AlertDialogDescription({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Description>) {
  return (
    <AlertDialogPrimitive.Description
      data-slot="alert-dialog-description"
      className={cn(
        // Body medium: 14px size, 20px line-height (matching Dialog)
        'text-sm leading-5 font-normal',
        'text-[var(--color-text-primary)]',
        className
      )}
      {...props}
    />
  )
}

function AlertDialogAction({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Action>) {
  return (
    <AlertDialogPrimitive.Action
      className={cn(buttonVariants({ variant: 'default' }), className)}
      {...props}
    />
  )
}

function AlertDialogCancel({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Cancel>) {
  return (
    <AlertDialogPrimitive.Cancel
      className={cn(buttonVariants({ variant: 'secondary' }), className)}
      {...props}
    />
  )
}

export {
  AlertDialog,
  AlertDialogPortal,
  AlertDialogOverlay,
  AlertDialogTrigger,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogBody,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogDescription,
  AlertDialogAction,
  AlertDialogCancel,
  alertDialogContentVariants,
}

