"use client"

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const badgeVariants = cva(
  "inline-flex items-center justify-center rounded-[4px] font-semibold whitespace-nowrap shrink-0 [&>svg]:pointer-events-none gap-1 transition-colors",
  {
    variants: {
      variant: {
        filled: "",
        outline: "border bg-[var(--color-surface-widget)]",
      },
      color: {
        default: "",
        sky: "",
        grass: "",
        bored: "",
        negative: "",
        neutral: "",
        dark: "",
      },
      size: {
        sm: "px-1 py-0.5 text-xs leading-4 h-5",
        default: "px-1.5 py-0.5 text-sm leading-5 h-6",
        lg: "px-2 py-0.5 text-base leading-6 h-7",
      },
    },
    compoundVariants: [
      // Filled variants
      {
        variant: "filled",
        color: "default",
        className: "bg-[var(--color-badge-filled-default-bg)] text-[var(--color-badge-filled-default-text)]",
      },
      {
        variant: "filled",
        color: "sky",
        className: "bg-[var(--color-badge-filled-sky-bg)] text-[var(--color-badge-filled-sky-text)]",
      },
      {
        variant: "filled",
        color: "grass",
        className: "bg-[var(--color-badge-filled-grass-bg)] text-[var(--color-badge-filled-grass-text)]",
      },
      {
        variant: "filled",
        color: "bored",
        className: "bg-[var(--color-badge-filled-bored-bg)] text-[var(--color-badge-filled-bored-text)]",
      },
      {
        variant: "filled",
        color: "negative",
        className: "bg-[var(--color-badge-filled-negative-bg)] text-[var(--color-badge-filled-negative-text)]",
      },
      {
        variant: "filled",
        color: "neutral",
        className: "bg-[var(--color-badge-filled-neutral-bg)] text-[var(--color-badge-filled-neutral-text)] border border-[var(--color-badge-filled-neutral-border)]",
      },
      {
        variant: "filled",
        color: "dark",
        className: "bg-[var(--color-badge-filled-dark-bg)] text-[var(--color-badge-filled-dark-text)]",
      },
      // Outline variants
      {
        variant: "outline",
        color: "default",
        className: "border-[var(--color-badge-outline-default-border)] text-[var(--color-badge-outline-default-text)]",
      },
      {
        variant: "outline",
        color: "sky",
        className: "border-[var(--color-badge-outline-sky-border)] text-[var(--color-badge-outline-sky-text)]",
      },
      {
        variant: "outline",
        color: "grass",
        className: "border-[var(--color-badge-outline-grass-border)] text-[var(--color-badge-outline-grass-text)]",
      },
      {
        variant: "outline",
        color: "bored",
        className: "border-[var(--color-badge-outline-bored-border)] text-[var(--color-badge-outline-bored-text)]",
      },
      {
        variant: "outline",
        color: "negative",
        className: "border-[var(--color-badge-outline-negative-border)] text-[var(--color-badge-outline-negative-text)]",
      },
      {
        variant: "outline",
        color: "neutral",
        className: "border-[var(--color-badge-outline-neutral-border)] text-[var(--color-badge-outline-neutral-text)]",
      },
      {
        variant: "outline",
        color: "dark",
        className: "border-[var(--color-badge-outline-dark-border)] text-[var(--color-badge-outline-dark-text)]",
      },
    ],
    defaultVariants: {
      variant: "filled",
      color: "default",
      size: "default",
    },
  }
)

export interface BadgeProps
  extends React.ComponentProps<"span">,
    VariantProps<typeof badgeVariants> {
  asChild?: boolean
}

function Badge({
  className,
  variant,
  color,
  size,
  asChild = false,
  ...props
}: BadgeProps) {
  const Comp = asChild ? Slot : "span"

  return (
    <Comp
      data-slot="badge"
      className={cn(badgeVariants({ variant, color, size }), className)}
      {...props}
    />
  )
}

export { Badge, badgeVariants }

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { ChevronRight, MoreHorizontal } from "lucide-react"

import { cn } from "@/lib/utils"
import { Link } from "@/components/ui/link"

/* ===========================================
   Individual Breadcrumb Components (shadcn API)
   =========================================== */

function Breadcrumb({ className, ...props }: React.ComponentProps<"nav">) {
  return (
    <nav
      aria-label="breadcrumb"
      data-slot="breadcrumb"
      className={cn("flex items-center", className)}
      {...props}
    />
  )
}

function BreadcrumbList({ className, ...props }: React.ComponentProps<"ol">) {
  return (
    <ol
      data-slot="breadcrumb-list"
      className={cn(
        "flex flex-wrap items-center gap-0 text-sm break-words list-none p-0 m-0",
        className
      )}
      {...props}
    />
  )
}

function BreadcrumbItem({ className, ...props }: React.ComponentProps<"li">) {
  return (
    <li
      data-slot="breadcrumb-item"
      className={cn("inline-flex items-center", className)}
      {...props}
    />
  )
}

function BreadcrumbLink({
  asChild,
  className,
  ...props
}: React.ComponentProps<"a"> & {
  asChild?: boolean
}) {
  const Comp = asChild ? Slot : Link

  return (
    <Comp
      data-slot="breadcrumb-link"
      className={cn(
        "text-sm font-semibold text-[var(--color-text-link-default)] underline hover:text-[var(--color-text-link-hover)] hover:no-underline",
        className
      )}
      {...props}
    />
  )
}

function BreadcrumbPage({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="breadcrumb-page"
      role="link"
      aria-disabled="true"
      aria-current="page"
      className={cn(
        "text-sm font-normal text-[var(--color-text-primary)] no-underline",
        className
      )}
      {...props}
    />
  )
}

function BreadcrumbSeparator({
  children,
  className,
  ...props
}: React.ComponentProps<"li">) {
  return (
    <li
      data-slot="breadcrumb-separator"
      role="presentation"
      aria-hidden="true"
      className={cn(
        "mx-1.5 flex items-center text-[var(--color-icon-brand)] [&>svg]:size-4",
        className
      )}
      {...props}
    >
      {children ?? <ChevronRight />}
    </li>
  )
}

function BreadcrumbEllipsis({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="breadcrumb-ellipsis"
      role="presentation"
      aria-hidden="true"
      className={cn("flex size-9 items-center justify-center", className)}
      {...props}
    >
      <MoreHorizontal className="size-4" />
      <span className="sr-only">More</span>
    </span>
  )
}

/* ===========================================
   Composite Breadcrumbs Component (Old API)
   =========================================== */

export interface BreadcrumbItemData {
  text: string
  href?: string
}

export interface BreadcrumbsProps extends React.ComponentProps<"nav"> {
  /**
   * An array of breadcrumb items.
   * Each item is an object with `text` and optional `href`.
   * The last item is considered the current page.
   */
  items: BreadcrumbItemData[]
}

const Breadcrumbs = React.forwardRef<HTMLElement, BreadcrumbsProps>(
  ({ items, className, ...rest }, ref) => {
    if (!items || items.length <= 1) {
      return null
    }

    return (
      <Breadcrumb ref={ref} className={className} {...rest}>
        <BreadcrumbList>
          {items.map((item, index) => {
            const isCurrentPage = index === items.length - 1

            return (
              <React.Fragment key={index}>
                <BreadcrumbItem aria-current={isCurrentPage ? "page" : undefined}>
                  {isCurrentPage ? (
                    <BreadcrumbPage>{item.text}</BreadcrumbPage>
                  ) : (
                    <BreadcrumbLink href={item.href || "#"}>
                      {item.text}
                    </BreadcrumbLink>
                  )}
                </BreadcrumbItem>
                {!isCurrentPage && <BreadcrumbSeparator />}
              </React.Fragment>
            )
          })}
        </BreadcrumbList>
      </Breadcrumb>
    )
  }
)

Breadcrumbs.displayName = "Breadcrumbs"

export {
  Breadcrumb,
  BreadcrumbList,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbPage,
  BreadcrumbSeparator,
  BreadcrumbEllipsis,
  Breadcrumbs,
}

"use client"

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex flex-row flex-nowrap items-center justify-center gap-1 whitespace-nowrap rounded-[var(--radius-xs)] font-semibold transition-all disabled:pointer-events-none disabled:cursor-not-allowed [&_svg]:pointer-events-none [&_svg]:shrink-0 outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--denim-300)]",
  {
    variants: {
      variant: {
        // Primary (default) - solid blue button
        default:
          "bg-[var(--color-surface-button-primary-default)] text-[var(--color-text-button-primary-default)] hover:bg-[var(--color-surface-button-primary-hover)] active:bg-[var(--color-surface-button-primary-pressed)] focus-visible:bg-[var(--color-surface-button-primary-focused)] disabled:bg-[var(--color-surface-button-primary-disabled)] disabled:text-[var(--color-text-button-primary-disabled)]",
        // Destructive/Error - solid red button
        destructive:
          "bg-[var(--color-surface-button-error-default)] text-[var(--color-text-button-error-default)] hover:bg-[var(--color-surface-button-error-hover)] active:bg-[var(--color-surface-button-error-pressed)] focus-visible:bg-[var(--color-surface-button-error-focused)] disabled:bg-[var(--color-surface-button-error-disabled)] disabled:text-[var(--color-text-button-error-disabled)]",
        // Outline/Secondary - bordered button
        outline:
          "bg-[var(--color-surface-button-secondary-default)] text-[var(--color-text-button-secondary-default)] border border-[var(--color-stroke-button-secondary-default)] hover:bg-[var(--color-surface-button-secondary-hover)] hover:text-[var(--color-text-button-secondary-hover)] hover:border-[var(--color-stroke-button-secondary-hover)] active:bg-[var(--color-surface-button-secondary-pressed)] active:text-[var(--color-text-button-secondary-pressed)] active:border-[var(--color-stroke-button-secondary-pressed)] focus-visible:bg-[var(--color-surface-button-secondary-focused)] disabled:bg-[var(--color-surface-button-secondary-disabled)] disabled:text-[var(--color-text-button-secondary-disabled)] disabled:border-[var(--color-stroke-default)]",
        // Secondary/Tertiary - light blue background
        secondary:
          "bg-[var(--color-surface-button-tertiary-default)] text-[var(--color-text-button-tertiary-default)] hover:bg-[var(--color-surface-button-tertiary-hover)] active:bg-[var(--color-surface-button-tertiary-pressed)] focus-visible:bg-[var(--color-surface-button-tertiary-focused)] disabled:bg-[var(--color-surface-button-tertiary-disabled)] disabled:text-[var(--color-text-button-tertiary-disabled)]",
        // Ghost - deprecated, kept for backward compatibility
        ghost:
          "hover:bg-accent hover:text-accent-foreground",
        // Link - deprecated, use Link component instead
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "min-w-[72px] h-9 px-2 py-1.5 text-sm [&_svg]:size-5",
        sm: "min-w-[56px] h-6 px-1 py-1 text-xs [&_svg]:size-3",
        lg: "min-w-[88px] h-10 px-3 py-2 text-base [&_svg]:size-6",
        icon: "size-9 p-2",
        "icon-sm": "size-6 p-1",
        "icon-lg": "size-10 p-2",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

export interface ButtonProps
  extends React.ComponentProps<"button">,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean
  isLoading?: boolean
  /** @deprecated Prefer placing the icon directly inside the button before the label. Use IconButton for icon-only actions. */
  icon?: React.ReactNode
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant,
      size,
      asChild = false,
      isLoading = false,
      icon,
      children,
      disabled,
      ...props
    },
    ref
  ) => {
    const localRef = React.useRef<HTMLButtonElement | null>(null)
    const composedRef = React.useCallback(
      (node: HTMLButtonElement | null) => {
        localRef.current = node
        if (typeof ref === "function") {
          ref(node)
        } else if (ref) {
          ;(ref as React.MutableRefObject<HTMLButtonElement | null>).current = node
        }
      },
      [ref]
    )
    const Comp = asChild ? Slot : "button"

    // Loading dots component
    const LoadingDots = () => (
      <span className="flex items-center justify-center gap-0.5">
        <span className="size-1 rounded-full bg-current animate-[flicker_1.4s_infinite_both]" />
        <span className="size-1 rounded-full bg-current animate-[flicker_1.4s_0.2s_infinite_both]" />
        <span className="size-1 rounded-full bg-current animate-[flicker_1.4s_0.4s_infinite_both]" />
      </span>
    )

    if (asChild) {
      return (
        <Comp
          ref={composedRef}
          data-slot="button"
          className={cn(buttonVariants({ variant, size }), className)}
          disabled={disabled || isLoading}
          data-loading={isLoading ? "" : undefined}
          {...props}
        >
          {children}
        </Comp>
      )
    }

    return (
      <Comp
        ref={composedRef}
        data-slot="button"
        className={cn(
          buttonVariants({ variant, size }),
          isLoading && "cursor-wait",
          className
        )}
        disabled={disabled || isLoading}
        data-loading={isLoading ? "" : undefined}
        {...props}
      >
        {isLoading ? (
          <LoadingDots />
        ) : (
          <span className="inline-flex flex-row flex-nowrap items-center gap-1">
            {icon && <span className="inline-flex items-center justify-center shrink-0">{icon}</span>}
            {children && <span className="px-1">{children}</span>}
          </span>
        )}
      </Comp>
    )
  }
)

Button.displayName = "Button"

export { Button, buttonVariants }

