"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

export type ChipColor = "grey" | "white"
export type ChipSize = "default" | "sm"

const chipVariants = cva(
  [
    "inline-flex w-fit shrink-0 items-center justify-center gap-[var(--spacing-sp-4)] whitespace-nowrap rounded-[var(--radius-s)] border px-[var(--spacing-sp-4)]",
    "border-[length:var(--border-width-100)] shadow-none outline-none transition-colors",
    "[&_[data-slot=chip-leading-icon]]:inline-flex [&_[data-slot=chip-leading-icon]]:shrink-0 [&_[data-slot=chip-leading-icon]>*]:size-4",
    "[&_[data-slot=chip-remove]]:inline-flex [&_[data-slot=chip-remove]]:shrink-0 [&_[data-slot=chip-remove]>*]:size-4",
    "[&_[data-slot=chip-label]]:truncate",
  ],
  {
    variants: {
      color: {
        grey: "",
        white: "",
      },
      size: {
        default:
          "h-8 [font:var(--font-body-medium-semibold)]",
        sm:
          "h-6 [font:var(--font-body-small-semibold)]",
      },
      selected: {
        true: "",
        false: "",
      },
      clickable: {
        true:
          "cursor-pointer focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--focus-ring-color)]",
        false: "",
      },
      disabled: {
        true:
          "cursor-not-allowed opacity-60 [&_[data-slot=chip-label]]:text-[var(--color-text-disabled)] [&_[data-slot=chip-leading-icon]]:text-[var(--color-icon-disabled)] [&_[data-slot=chip-remove]]:text-[var(--color-icon-disabled)]",
        false: "",
      },
      hasIcon: {
        true: "",
        false: "",
      },
      removable: {
        true: "",
        false: "",
      },
    },
    compoundVariants: [
      {
        color: "grey",
        selected: false,
        disabled: false,
        className:
          "bg-[var(--color-surface-chip-default)] border-[var(--color-stroke-light)] [&_[data-slot=chip-label]]:text-[var(--color-text-dark-accent)] [&_[data-slot=chip-leading-icon]]:text-[var(--color-icon-dark)] [&_[data-slot=chip-remove]]:text-[var(--color-icon-dark)]",
      },
      {
        color: "white",
        selected: false,
        disabled: false,
        className:
          "bg-[var(--color-surface-chip-default-white)] border-[var(--color-stroke-light)] [&_[data-slot=chip-label]]:text-[var(--color-text-dark-accent)] [&_[data-slot=chip-leading-icon]]:text-[var(--color-icon-dark)] [&_[data-slot=chip-remove]]:text-[var(--color-icon-dark)]",
      },
      {
        color: "grey",
        selected: true,
        disabled: false,
        className:
          "bg-[var(--color-surface-chip-selected)] border-[var(--color-stroke-brand)] [&_[data-slot=chip-label]]:text-[var(--color-text-selected)] [&_[data-slot=chip-leading-icon]]:text-[var(--color-icon-brand)] [&_[data-slot=chip-remove]]:text-[var(--color-icon-dark)]",
      },
      {
        color: "white",
        selected: true,
        disabled: false,
        className:
          "bg-[var(--color-surface-chip-selected)] border-[var(--color-stroke-brand)] [&_[data-slot=chip-label]]:text-[var(--color-text-selected)] [&_[data-slot=chip-leading-icon]]:text-[var(--color-icon-brand)] [&_[data-slot=chip-remove]]:text-[var(--color-icon-dark)]",
      },
      {
        color: "grey",
        size: "default",
        selected: false,
        clickable: true,
        disabled: false,
        className:
          "hover:bg-[var(--color-surface-chip-hover)] hover:border-[var(--brand-350)]",
      },
      {
        color: "white",
        size: "default",
        selected: false,
        clickable: true,
        disabled: false,
        className:
          "hover:bg-[var(--color-surface-chip-hover)] hover:border-[var(--brand-350)]",
      },
      {
        color: "grey",
        size: "sm",
        selected: false,
        clickable: true,
        disabled: false,
        className:
          "hover:bg-[var(--color-surface-chip-default)] hover:border-[var(--brand-350)]",
      },
      {
        color: "white",
        size: "sm",
        selected: false,
        clickable: true,
        disabled: false,
        className:
          "hover:bg-[var(--color-surface-chip-default)] hover:border-[var(--brand-350)]",
      },
    ],
    defaultVariants: {
      color: "grey",
      size: "default",
      selected: false,
      clickable: false,
      disabled: false,
      hasIcon: false,
      removable: false,
    },
  }
)

export interface ChipProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onClick">,
    VariantProps<typeof chipVariants> {
  children: React.ReactNode
  color?: ChipColor
  size?: ChipSize
  selected?: boolean
  disabled?: boolean
  icon?: React.ReactNode
  onClick?: (event: React.MouseEvent<HTMLDivElement>) => void
  onRemove?: (event: React.MouseEvent<HTMLButtonElement>) => void
  removeLabel?: string
}

const Chip = React.forwardRef<HTMLDivElement, ChipProps>(
  (
    {
      children,
      color = "grey",
      size = "default",
      selected = false,
      disabled = false,
      icon,
      onClick,
      onRemove,
      removeLabel = "Remove chip",
      className,
      onKeyDown,
      ...props
    },
    ref
  ) => {
    const clickable = Boolean(onClick) && !disabled
    const removable = Boolean(onRemove)
    const hasIcon = Boolean(icon)

    const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
      onKeyDown?.(event)

      if (event.defaultPrevented || !clickable) {
        return
      }

      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault()
        event.currentTarget.click()
      }
    }

    const handleRemoveClick = (event: React.MouseEvent<HTMLButtonElement>) => {
      event.stopPropagation()
      onRemove?.(event)
    }

    return (
      <div
        ref={ref}
        data-slot="chip"
        data-selected={selected ? "" : undefined}
        data-disabled={disabled ? "" : undefined}
        role={clickable ? "button" : undefined}
        tabIndex={clickable ? 0 : undefined}
        aria-pressed={clickable ? selected : undefined}
        aria-disabled={disabled || undefined}
        onClick={clickable ? onClick : undefined}
        onKeyDown={handleKeyDown}
        className={cn(
          chipVariants({
            color,
            size,
            selected,
            clickable,
            disabled,
            hasIcon,
            removable,
          }),
          className
        )}
        {...props}
      >
        {icon ? <span data-slot="chip-leading-icon">{icon}</span> : null}
        <span data-slot="chip-label">{children}</span>
        {onRemove ? (
          <button
            type="button"
            data-slot="chip-remove"
            className="inline-flex items-center justify-center rounded-[var(--radius-xs)] bg-transparent p-0 outline-none focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-[var(--focus-ring-color)] disabled:cursor-not-allowed"
            aria-label={removeLabel}
            disabled={disabled}
            onClick={handleRemoveClick}
          >
            <svg
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden="true"
            >
              <path d="M18 6L6 18" />
              <path d="M6 6l12 12" />
            </svg>
          </button>
        ) : null}
      </div>
    )
  }
)

Chip.displayName = "Chip"

export { Chip, chipVariants }

'use client'

import * as React from 'react'
import * as CheckboxPrimitive from '@radix-ui/react-checkbox'
import { Check, Minus } from 'lucide-react'
import { cva, type VariantProps } from 'class-variance-authority'

import { cn } from '@/lib/utils'

const checkboxVariants = cva(
  [
    'peer shrink-0 flex items-center justify-center rounded-[var(--radius-xxs)]',
    'border-2 border-[var(--color-stroke-controls-default)] bg-transparent',
    'transition-colors duration-200 ease-out',
    'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--color-surface-focused)]',
    // Unchecked hover
    'hover:not-disabled:data-[state=unchecked]:border-[var(--color-stroke-controls-hover)]',
    // Checked state
    'data-[state=checked]:bg-[var(--color-surface-controls-selected)] data-[state=checked]:border-0',
    'hover:not-disabled:data-[state=checked]:bg-[var(--color-surface-controls-hover)]',
    // Indeterminate state
    'data-[state=indeterminate]:bg-[var(--color-surface-controls-selected)] data-[state=indeterminate]:border-0',
    'hover:not-disabled:data-[state=indeterminate]:bg-[var(--color-surface-controls-hover)]',
    // Disabled state
    'disabled:cursor-not-allowed',
    'disabled:data-[state=unchecked]:bg-[var(--color-surface-controls-disabled)] disabled:data-[state=unchecked]:border-[var(--color-stroke-controls-disabled)]',
    'disabled:data-[state=checked]:bg-[var(--color-surface-controls-locked)]',
    'disabled:data-[state=indeterminate]:bg-[var(--color-surface-controls-locked)]',
  ],
  {
    variants: {
      size: {
        sm: 'size-[18px]',
        default: 'size-6',
      },
    },
    defaultVariants: {
      size: 'sm',
    },
  }
)

const iconVariants = cva('text-white', {
  variants: {
    size: {
      sm: '',
      default: '',
    },
  },
  defaultVariants: {
    size: 'sm',
  },
})

export type CheckboxSize = 'sm' | 'default'

export interface CheckboxProps
  extends Omit<React.ComponentPropsWithoutRef<typeof CheckboxPrimitive.Root>, 'asChild'>,
    VariantProps<typeof checkboxVariants> {
  /**
   * A label to be displayed next to the checkbox.
   */
  label?: React.ReactNode
  /**
   * Additional supporting text to be displayed.
   */
  supportingText?: React.ReactNode
}

const Checkbox = React.forwardRef<
  React.ComponentRef<typeof CheckboxPrimitive.Root>,
  CheckboxProps
>(({ className, size = 'sm', label, supportingText, id: providedId, disabled, checked, ...props }, ref) => {
  const generatedId = React.useId()
  const checkboxId = providedId || generatedId

  const hasTextContent = label || supportingText

  // Icon sizes based on checkbox size
  const checkIconSize = size === 'default' ? 'size-4' : 'size-3'
  const minusIconSize = size === 'default' ? 'size-3' : 'size-2'

  // Determine which icon to show based on checked state
  const isIndeterminate = checked === 'indeterminate'

  const checkboxElement = (
    <CheckboxPrimitive.Root
      ref={ref}
      id={checkboxId}
      data-slot="checkbox"
      disabled={disabled}
      checked={checked}
      className={cn(checkboxVariants({ size }), className)}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className={cn(
          'flex items-center justify-center',
          iconVariants({ size }),
          disabled && 'text-[var(--color-text-controls-disabled)]'
        )}
      >
        {isIndeterminate ? (
          <Minus className={cn(minusIconSize, 'stroke-[2px]')} aria-hidden />
        ) : (
          <Check className={checkIconSize} aria-hidden />
        )}
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )

  // If no label/supporting text, return just the checkbox
  if (!hasTextContent) {
    return checkboxElement
  }

  // Return checkbox with label/supporting text wrapper
  return (
    <div
      data-slot="checkbox-wrapper"
      className={cn(
        'flex items-start gap-3',
        disabled && 'cursor-not-allowed'
      )}
    >
      {checkboxElement}
      <div className="flex flex-col gap-0.5">
        {label && (
          <label
            htmlFor={checkboxId}
            className={cn(
              'cursor-pointer font-semibold text-[var(--color-text-primary)]',
              size === 'default' ? 'text-base leading-6' : 'text-sm leading-5',
              disabled && 'cursor-not-allowed text-[var(--color-text-controls-disabled)]'
            )}
          >
            {label}
          </label>
        )}
        {supportingText && (
          <span
            className={cn(
              'text-[var(--color-text-secondary)]',
              size === 'default' ? 'text-base leading-6' : 'text-sm leading-5'
            )}
          >
            {supportingText}
          </span>
        )}
      </div>
    </div>
  )
})

Checkbox.displayName = 'Checkbox'

export { Checkbox, checkboxVariants }

