  onBack?: () => void
  /** Custom footer content */
  footerContent?: React.ReactNode
  /** Hide the close button */
  hideCloseButton?: boolean
}

const DrawerContent = React.forwardRef<
  React.ElementRef<typeof DrawerPrimitive.Content>,
  DrawerContentProps
>(
  (
    {
      className,
      children,
      headerTitle,
      onBack,
      footerContent,
      hideCloseButton = false,
