                  // Right side positioning (default)
                  'rounded-l-[var(--radius-s)]',
                  'inset-y-0 right-0',
                  'w-[578px] min-w-[360px] max-w-[90vw]',
                  'h-screen',
                  'data-[state=open]:slide-in-from-right data-[state=closed]:slide-out-to-right',
                ],
