  --primary-foreground: oklch(1.00 0 0);
  --secondary: oklch(0.38 0.01 250);
  --secondary-foreground: oklch(1.00 0 0);
  --muted: oklch(0.38 0.01 250);
  --muted-foreground: oklch(0.77 0.01 250);
  --accent: oklch(0.38 0.01 250);
  --accent-foreground: oklch(1.00 0 0);
  --destructive: oklch(0.43 0.16 25);
  --destructive-foreground: oklch(1.00 0 0);
  --border: oklch(0.43 0.01 250);
  --input: oklch(0.43 0.01 250);
  --ring: oklch(0.71 0.14 254);
  --sidebar: oklch(0.27 0.01 250);
