  --sidebar-accent-foreground: oklch(1.00 0 0);
  --sidebar-border: oklch(0.43 0.01 250);
  --sidebar-ring: oklch(0.71 0.14 254);

  color-scheme: dark;

  /* ===========================================
     BRD SEMANTIC TOKENS - DARK
     Only SEMANTIC tokens are remapped here. Raw palette
     primitives (grey-*, blue-*, red-*, ...) are NOT touched.
     Every value references an existing primitive so the
     dark theme stays inside the registry token set.
     =========================================== */

  /* ---------- Surfaces ---------- */
  --color-surface-background: var(--grey-1100);          /* 0.18 - shell base */
  --color-surface-dashboard: var(--grey-1050);           /* 0.23 - content area */
  --color-surface-foreground: var(--grey-1000);          /* 0.27 - header/nav/popover (elevated) */
