  --color-surface-progress-active: var(--blue-400);
  --color-surface-progress-foreground: var(--blue-800);

  /* Controls */
  --color-surface-controls-selected: var(--blue-400);
  --color-surface-controls-hover: var(--blue-450);
  --color-surface-controls-disabled: var(--grey-900);
  --color-surface-controls-locked: var(--grey-900);

  /* Button group / toggle */
  --color-surface-button-group-background: var(--grey-1050);
