  /* Links */
  --color-text-link-default: var(--blue-350);
  --color-text-link-hover: var(--blue-300);
  --color-text-link-pressed: var(--blue-250);
  --color-text-link-visited: var(--chetwode-300);
  --color-text-link-disabled: var(--grey-700);

  /* Controls text */
  --color-text-controls-default: var(--grey-100);
  --color-text-controls-focused: var(--grey-100);
  --color-text-controls-hover: var(--grey-100);
  --color-text-controls-selected: var(--grey-100);
  --color-text-controls-locked: var(--grey-600);
  --color-text-controls-disabled: var(--grey-700);

  /* Secondary button text */
  --color-text-button-secondary-default: var(--grey-450);
