  --color-text-button-tertiary-disabled: var(--grey-700);

  /* ---------- Strokes ---------- */
  --color-stroke-default: var(--grey-900);
  --color-stroke-divider: var(--grey-950);
  --color-stroke-dark: var(--grey-300);                  /* emphasis border inverts to light */
  --color-stroke-light: var(--grey-1000);
  --color-stroke-strong: var(--grey-200);                /* inverts */
  --color-stroke-table: var(--grey-950);
  --color-stroke-disabled: var(--grey-900);
  --color-stroke-brand: var(--blue-350);
  --color-border-neutral-subtle: var(--grey-1000);

  /* Secondary button strokes */
  --color-stroke-button-secondary-default: var(--grey-700);
