  --color-stroke-button-secondary-focused: var(--blue-350);
  --color-stroke-button-secondary-disabled: var(--grey-900);

  /* Controls strokes */
  --color-stroke-controls-default: var(--grey-700);
  --color-stroke-controls-hover: var(--grey-300);
  --color-stroke-controls-disabled: var(--grey-900);

  /* ---------- Icons ---------- */
  --color-icon-dark: var(--grey-100);
  --color-icon-disabled: var(--grey-700);
  --color-icon-brand: var(--blue-350);

  /* ---------- State (accents lifted for dark contrast) ---------- */
  --color-state-error: var(--red-300);                   /* red-300 clears AA 4.5:1 on dark surfaces */
  --color-state-success: var(--green-400);
  --color-state-warning: var(--orange-400);
  --color-state-error-medium: var(--red-300);

  /* ---------- Navigation ---------- */
  --color-navigation-active: var(--blue-350);
  --color-navigation-hover: var(--grey-950);
