  --status-success-stroke: var(--green-700);
  --status-warning-light: var(--orange-900);
  --status-warning-stroke: var(--orange-700);
  --warning-light: var(--orange-900);

  /* ---------- Alerts ---------- */
  --color-alert-info-bg: var(--blue-800);
  --color-alert-info-border: var(--blue-700);
  --color-alert-info-icon: var(--blue-350);
  --color-alert-success-bg: var(--green-900);
  --color-alert-success-border: var(--green-700);
  --color-alert-success-icon: var(--green-400);
