/** Donut chart that reflows when its container resizes (grid span changes). */
function AllocationDonut({ height }: { height: number }) {
  const ref = React.useRef<HighchartsReact.RefObject>(null)
  const wrapRef = React.useRef<HTMLDivElement>(null)

  React.useEffect(() => {
    const node = wrapRef.current
    if (!node) return
    const observer = new ResizeObserver(() => {
      ref.current?.chart?.reflow()
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [])

  const options = React.useMemo<Highcharts.Options>(
    () => ({
      chart: { type: 'pie', height, backgroundColor: 'transparent', spacing: [0, 0, 0, 0] },
      title: { text: undefined },
      tooltip: { pointFormat: '<b>{point.percentage:.0f}%</b> ({point.y})' },
      plotOptions: {
        pie: {
          innerSize: '72%',
          borderWidth: 0,
          dataLabels: { enabled: false },
        },
      },
      legend: { enabled: false },
      series: [
        {
          type: 'pie',
          name: 'Allocation',
          data: ALLOCATION.map((r) => ({ name: r.assetClass, y: r.pct })),
        },
      ],
    }),
    [height]
  )

  return (
    <div ref={wrapRef} className="relative w-full" style={{ height }}>
      <HighchartsReact ref={ref} highcharts={Highcharts} options={options} />
      <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center">
        <span className="text-[var(--color-text-secondary)] [font:var(--font-body-medium)]">
